```sql
CREATE PROCEDURE TransferFunds
    @FromAccountID INT,
    @ToAccountID INT,
    @Amount DECIMAL(18, 2),
    @TransactionID INT
AS
BEGIN
    BEGIN TRANSACTION;

    IF (SELECT Balance FROM Accounts WHERE AccountID = @FromAccountID) >= @Amount
    BEGIN
        UPDATE Accounts SET Balance = Balance - @Amount WHERE AccountID = @FromAccountID;
        UPDATE Accounts SET Balance = Balance + @Amount WHERE AccountID = @ToAccountID;
        INSERT INTO Transactions (TransactionID, FromAccountID, ToAccountID, Amount)
        VALUES (@TransactionID, @FromAccountID, @ToAccountID, @Amount);

        COMMIT;
    END
    ELSE
    BEGIN
        ROLLBACK;
    END
END;
```

